  const [daemonTime, setDaemonTime] = useState(0.1);
  const [model, setModel] = useState('solomon'); // 'maxwell' or 'solomon'
  const [particles, setParticles] = useState([]);
  const [dustPackets, setDustPackets] = useState([]);
  const [entropy, setEntropy] = useState({ system: 0, daemon: 0, total: 0 });
  const [phaseData, setPhaseData] = useState([]);

  // Configuration
  const [config, setConfig] = useState({
    numParticles: 12,
    boxWidth: 400,
    boxHeight: 300,
    temperature: 1.0,
    speed: 1.0,
    showDust: true,
    showDoors: true,
    showPhase: true,
    dustLifetime: 50,
    tau: 2 * Math.PI
  });

  const canvasRef = useRef(null);
  const animationRef = useRef(null);

  // Mathematical functions for Solomon's daemon
  const f = (k) => {
    if (k <= 0) return 0;
    return Math.log(k * Math.PI) / Math.log(2 * Math.PI);
  };

  const I = (k) => {
    const fk = f(k);
    return fk - Math.floor(fk);
  };

  const moodBit = (k, tau = 2 * Math.PI) => {
    return Math.sign(Math.cos(Math.pow(tau, k)));
  };

  const daemonClockFunctor = (k, tau = 2 * Math.PI) => {
    return Math.exp(1j * Math.pow(tau, k)) / tau; // Conceptual - using phase for visualization
  };

  const observerClockFunctor = (k, tau = 2 * Math.PI) => {
    return Math.exp(1j * tau / k) / tau; // Conceptual - using phase for visualization
  };

  // Initialize particles
  const initializeParticles = useCallback(() => {
    const newParticles = [];
    for (let i = 0; i < config.numParticles; i++) {
      newParticles.push({
        id: i,
        x: Math.random() * config.boxWidth,
        y: Math.random() * config.boxHeight,
        vx: (Math.random() - 0.5) * 4 * config.speed,
        vy: (Math.random() - 0.5) * 4 * config.speed,
        speed: Math.random() * 2 + 0.5,
        doorOpen: false,
        moodBit: 1,
        lastDoorTime: 0,
        angle: Math.random() * 2 * Math.PI,
        mass: 1
      });
    }
    setParticles(newParticles);
  }, [config.numParticles, config.boxWidth, config.boxHeight, config.speed]);

  // Solomon's daemon door logic
  const updateSolomonDoors = (k, particles) => {
    const N = particles.length;
    const activeParticleIndex = Math.floor(k) % N;

    return particles.map((particle, i) => ({
      ...particle,
      doorOpen: i === activeParticleIndex
    }));
  };

  // Maxwell's demon door logic
  const updateMaxwellDoors = (particles, threshold = 1.5) => {
    return particles.map(particle => ({
      ...particle,
      doorOpen: particle.speed > threshold
    }));
  };

  // Create dust packet
  const createDustPacket = (particle, mood) => {
    return {
      id: Date.now() + Math.random(),
      x: particle.x,
      y: particle.y,
      vx: (Math.random() - 0.5) * 2,
      vy: (Math.random() - 0.5) * 2,
      mood: mood,
      lifetime: config.dustLifetime,
      age: 0
    };
  };

  // Update dust packets
  const updateDustPackets = (packets, particles) => {
    const updatedPackets = packets
      .map(packet => ({
        ...packet,
        x: packet.x + packet.vx,
        y: packet.y + packet.vy,
        age: packet.age + 1
      }))
      .filter(packet => packet.age < packet.lifetime);

    // Check for collisions with particles
    updatedPackets.forEach(packet => {
      particles.forEach(particle => {
        const dx = packet.x - particle.x;
        const dy = packet.y - particle.y;
        const distance = Math.sqrt(dx * dx + dy * dy);

        if (distance < 15 && packet.age > 1) {
          // Transfer mood bit and adjust trajectory
          particle.moodBit = packet.mood;
          particle.angle += packet.mood * 0.1;
          particle.vx += Math.cos(particle.angle) * 0.1;
          particle.vy += Math.sin(particle.angle) * 0.1;
          packet.lifetime = 0; // Mark for removal
        }
      });
    });

    return updatedPackets.filter(packet => packet.lifetime > 0);
  };

