        if (newY <= 10 || newY >= config.boxHeight - 10) {
          newVy = -newVy;
          newY = Math.max(10, Math.min(config.boxHeight - 10, newY));
        }

        const speed = Math.sqrt(newVx * newVx + newVy * newVy);

