          const newDust = [];

          updatedParticles.forEach(particle => {
            if (particle.doorOpen && Math.random() < 0.1) {
              newDust.push(createDustPacket(particle, mood));
            }
          });

          if (newDust.length > 0) {
            setDustPackets(prev => [...prev, ...newDust]);
          }

          // Store phase data for plotting
          setPhaseData(prev => {
            const newData = [...prev, {
              k: newK,
              I: I(newK),
              mood: mood,
              alignment: Math.abs(I(newK)) < 0.01
            }];
            return newData.slice(-200); // Keep last 200 points
          });

          return newK;
        });
      } else {
        // Maxwell's demon logic
        updatedParticles = updateMaxwellDoors(updatedParticles);
      }

      return updatedParticles;
    });

    // Update dust packets
    setDustPackets(prev => updateDustPackets(prev, particles));

    // Calculate entropy
    setEntropy(calculateEntropy(particles, dustPackets, daemonTime));
  }, [model, config.tau, config.boxWidth, config.boxHeight, particles, dustPackets, daemonTime]);

  // Animation loop
  useEffect(() => {
    if (isRunning) {
      animationRef.current = setInterval(simulationStep, 50);
    } else {
      clearInterval(animationRef.current);
    }

    return () => clearInterval(animationRef.current);
  }, [isRunning, simulationStep]);

  // Initialize on mount
  useEffect(() => {
    initializeParticles();
  }, [initializeParticles]);

  // Canvas drawing
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw boundary
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 2;
    ctx.strokeRect(0, 0, config.boxWidth, config.boxHeight);

    // Draw particles
    particles.forEach(particle => {
      ctx.beginPath();
      ctx.arc(particle.x, particle.y, 8, 0, 2 * Math.PI);

      // Color based on speed and mood
      if (model === 'solomon') {
        ctx.fillStyle = particle.moodBit > 0 ? '#ff6b6b' : '#4ecdc4';
      } else {
        const speedRatio = particle.speed / 3;
        ctx.fillStyle = `hsl(${240 - speedRatio * 120}, 70%, 60%)`;
      }

      ctx.fill();

      // Draw door indicator
      if (config.showDoors && particle.doorOpen) {
        ctx.strokeStyle = '#ffd93d';
        ctx.lineWidth = 3;
        ctx.stroke();
      }
