// Solomon's daemon door logic
const updateSolomonDoors = (k, particles) => {
  // Before bang (k < 2), no doors open - pre-bang index sweep
  if (k < 2) {
    return particles.map(particle => ({
      ...particle,
      doorOpen: false
    }));
  }

  const N = particles.length;
  if (N === 0) return [];

  const activeParticleIndex = Math.floor(k) % N;

  return particles.map((particle, i) => ({
    ...particle,
    doorOpen: i === activeParticleIndex
  }));
};

// Calculate Landauer cost only on state changes
const calculateLandauerCost = (currentDoorStates, previousDoorStates, dustPackets, prevDustCount) => {
  let cost = 0;

  // Cost for door state changes (erasure when door closes)
  Object.keys(currentDoorStates).forEach(particleId => {
    const wasOpen = previousDoorStates[particleId] || false;
    const isOpen = currentDoorStates[particleId] || false;

    // Charge when door closes (erasure event)
    if (wasOpen && !isOpen) {
      cost += Math.log(2); // kBT ln(2) per bit erased
    }
  });

  // Cost for dust packet creation/destruction (information events)
  const dustCountChange = Math.abs(dustPackets.length - prevDustCount);
  if (dustCountChange > 0) {
    cost += dustCountChange * Math.log(2);
  }

  return cost;
};

