// Calculate entropy using proper thermodynamics
const calculateEntropy = (particles, dustPackets, k, landauerCost = 0) => {
  // System entropy: Shannon entropy of particle positions/speeds
  let systemEntropy = 0;

  if (particles.length > 0) {
    // Position entropy (spatial distribution)
    const bins = 8;
    const xBins = new Array(bins).fill(0);
    const yBins = new Array(bins).fill(0);

    particles.forEach(p => {
      const xBin = Math.min(bins - 1, Math.floor((p.x / config.boxWidth) * bins));
      const yBin = Math.min(bins - 1, Math.floor((p.y / config.boxHeight) * bins));
      xBins[xBin]++;
      yBins[yBin]++;
    });

    // Shannon entropy: S = -Σ p_i ln(p_i)
    const calculateShannonEntropy = (bins) => {
      const total = bins.reduce((sum, count) => sum + count, 0);
      return bins.reduce((entropy, count) => {
        if (count === 0) return entropy;
        const p = count / total;
        return entropy - p * Math.log(p);
      }, 0);
    };

    systemEntropy = calculateShannonEntropy(xBins) + calculateShannonEntropy(yBins);

    // Speed distribution entropy
    const speedBins = new Array(bins).fill(0);
    particles.forEach(p => {
      const speedBin = Math.min(bins - 1, Math.floor((p.speed / 4) * bins));
      speedBins[speedBin]++;
    });
    systemEntropy += calculateShannonEntropy(speedBins);
  }

  // Daemon entropy: accumulated Landauer cost from state changes
  const daemonEntropy = landauerCost;

  return {
    system: systemEntropy,
    daemon: daemonEntropy,
    total: systemEntropy + daemonEntropy
  };
};

