            newY = Math.max(10, Math.min(config.boxHeight - 10, newY));
          }

          const speed = Math.sqrt(newVx * newVx + newVy * newVy);

          return {
            ...particle,
            x: newX,
            y: newY,
            vx: newVx,
            vy: newVy,
            speed: speed
          };
        });

        // Update doors based on daemon time
        updatedParticles = updateSolomonDoors(newK, updatedParticles);

        // Track door state changes for Landauer cost
        const currentDoorStates = {};
        updatedParticles.forEach(particle => {
          const wasOpen = lastDoorStates[particle.id] || false;
          const isOpen = particle.doorOpen;
          currentDoorStates[particle.id] = isOpen;

          // Create dust packet deterministically when door opens
          if (isOpen && !wasOpen && hasBanged) {
            const mood = moodBit(newK, config.tau);
            const dustPacket = createDustPacket(particle, mood, true);
            if (dustPacket) {
              setDustPackets(prev => [...prev, dustPacket]);
            }
          }
        });

        setLastDoorStates(currentDoorStates);

        // Calculate Landauer cost and update entropy
        const landauerCost = calculateLandauerCost(currentDoorStates, prevDoorStates, dustPackets, prevDustCount);
        setEntropy(prev => ({
          ...calculateEntropy(updatedParticles, dustPackets, newK, prev.daemon + landauerCost)
        }));

        return updatedParticles;
      });

      // Store phase data for analysis
      const phaseGap = calculatePhaseGap(newK, config.tau);
      const isAlignment = Math.abs(I(newK)) < 0.001;

      setPhaseData(prev => {
        const newData = [...prev, {
          k: newK,
          I: I(newK),
          mood: moodBit(newK, config.tau),
          alignment: isAlignment,
          phaseGap: phaseGap,
          observerPhase: observerClockFunctor(newK, config.tau).phase,
          daemonPhase: daemonClockFunctor(newK, config.tau).phase,
          isBang: isAlignment && newK >= 1.99 && newK <= 2.01
        }];
        return newData.slice(-200); // Keep last 200 points
      });

      return newK;
    });
  } else {
    // Maxwell's demon logic (unchanged)
    setParticles(prevParticles => {
      let updatedParticles = prevParticles.map(particle => {
        // Update position
        let newX = particle.x + particle.vx;
        let newY = particle.y + particle.vy;
        let newVx = particle.vx;
        let newVy = particle.vy;

        // Boundary collisions
        if (newX <= 10 || newX >= config.boxWidth - 10) {
          newVx = -newVx;
          newX = Math.max(10, Math.min(config.boxWidth - 10, newX));
        }
        if (newY <= 10 || newY >= config.boxHeight - 10) {
          newVy = -newVy;
          newY = Math.max(10, Math.min(config.boxHeight - 10, newY));
        }

        const speed = Math.sqrt(newVx * newVx + newVy * newVy);

        return {
          ...particle,
          x: newX,
          y: newY,
          vx: newVx,
          vy: newVy,
          speed: speed
        };
      });

      // Maxwell's demon door logic
      updatedParticles = updateMaxwellDoors(updatedParticles);
      return updatedParticles;
    });
  }

  // Update dust packets
  setDustPackets(prev => updateDustPackets(prev, particles));
}, [model, config.tau, config.boxWidth, config.boxHeight, particles, dustPackets, hasBanged, triggerBang, lastDoorStates]);

