import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Play, Pause, RotateCcw, Settings, Download, Info, Thermometer, Zap } from 'lucide-react';

const Simulator = () => {
  // Physical constants (SI units)
  const kB = 1.380649e-23; // Boltzmann constant [J/K]
  const amu = 1.66054e-27; // Atomic mass unit [kg]
  const nm = 1e-9; // Nanometer to meter conversion

  // Molecular parameters for N2 at 300K
  const molecularParams = {
    mass: 28.014 * amu, // N2 molecular mass [kg]
    diameter: 3.798e-10, // N2 molecular diameter [m]
    temperature: 300, // Initial temperature [K]
    meanSpeed: Math.sqrt(8 * kB * 300 / (Math.PI * 28.014 * amu)) // ~430 m/s for N2
  };

  // Simulation state
  const [isRunning, setIsRunning] = useState(false);
  const [time, setTime] = useState(0); // Time in femtoseconds
  const [realTime, setRealTime] = useState(0); // Real physical time in seconds
  const [particles, setParticles] = useState([]);
  const [demonMemory, setDemonMemory] = useState([]);
  const [gateState, setGateState] = useState({ open: false, lastOperation: 0 });
  const [chambers, setChambers] = useState({
    left: { temperature: 300, entropy: 0, particleCount: 0 },
    right: { temperature: 300, entropy: 0, particleCount: 0 }
  });
  const [energetics, setEnergetics] = useState({
    totalEnergy: 0,
    systemEntropy: 0,
    demonEntropy: 0,
    landauerCost: 0,
    workExtracted: 0
  });

  // Configuration
  const [config, setConfig] = useState({
    numParticles: 200, // Manageable number for visualization
    chamberWidth: 200, // pixels (represents ~50 nm)
    chamberHeight: 150, // pixels (represents ~37.5 nm)
    partitionThickness: 4, // pixels (represents ~1 nm)
    gateSize: 12, // pixels (represents ~3 nm, about 8 molecular diameters)
    timeStep: 1.0, // femtoseconds
    speedScale: 0.1, // Visualization scaling factor
    demonEnabled: true,
    measurementPrecision: 0.05, // 5% velocity measurement uncertainty
    gateResponseTime: 0.5 // picoseconds
  });

  const canvasRef = useRef(null);
  const animationRef = useRef(null);

  // Generate Maxwell-Boltzmann distributed velocities
  const generateMaxwellBoltzmannVelocity = (temperature, mass) => {
    // Box-Muller transform for Gaussian random numbers
    const u1 = Math.random();
    const u2 = Math.random();
    const z0 = Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
    const z1 = Math.sqrt(-2 * Math.log(u1)) * Math.sin(2 * Math.PI * u2);

    // Convert to Maxwell-Boltzmann distribution
    const sigma = Math.sqrt(kB * temperature / mass);
    const vx = z0 * sigma;
    const vy = z1 * sigma;

    return { 
      vx: vx * config.speedScale, 
      vy: vy * config.speedScale,
      speed: Math.sqrt(vx * vx + vy * vy)
    };
  };

  // Initialize particles with proper Maxwell-Boltzmann distribution
  const initializeParticles = useCallback(() => {
    const newParticles = [];
    const leftChamberWidth = config.chamberWidth / 2 - config.partitionThickness / 2;
    const rightChamberStart = config.chamberWidth / 2 + config.partitionThickness / 2;

    for (let i = 0; i < config.numParticles; i++) {
      const isLeftChamber = i < config.numParticles / 2;
      const velocity = generateMaxwellBoltzmannVelocity(molecularParams.temperature, molecularParams.mass);

      newParticles.push({
        id: i,
        x: isLeftChamber 
          ? Math.random() * leftChamberWidth + 10
          : Math.random() * leftChamberWidth + rightChamberStart,
        y: Math.random() * (config.chamberHeight - 20) + 10,
        vx: velocity.vx,
        vy: velocity.vy,
        speed: velocity.speed,
        mass: molecularParams.mass,
        radius: 3, // Visualization radius
        chamber: isLeftChamber ? 'left' : 'right',
        measuredSpeed: null,
        lastMeasured: 0
      });
    }

    setParticles(newParticles);
    setDemonMemory([]);
    setGateState({ open: false, lastOperation: 0 });
  }, [config]);

  // Calculate molecular speed from kinetic energy
  const getMolecularSpeed = (vx, vy) => {
    return Math.sqrt(vx * vx + vy * vy) / config.speedScale;
  };

  // Demon measurement and decision logic
  const demonMeasurement = (particle, currentTime) => {
    if (!config.demonEnabled) return null;

    const actualSpeed = getMolecularSpeed(particle.vx, particle.vy);
    const measurementError = (Math.random() - 0.5) * 2 * config.measurementPrecision;
    const measuredSpeed = actualSpeed * (1 + measurementError);

    // Decision: fast molecules (> mean speed) go right, slow molecules go left
    const meanSpeed = molecularParams.meanSpeed;
    const shouldGoRight = measuredSpeed > meanSpeed;

    // Check if particle is approaching gate from correct direction
    const gateY = config.chamberHeight / 2;
    const isApproachingGate = Math.abs(particle.y - gateY) < config.gateSize / 2;
    const correctDirection = (particle.chamber === 'left' && shouldGoRight && particle.vx > 0) ||
                           (particle.chamber === 'right' && !shouldGoRight && particle.vx < 0);

    if (isApproachingGate && correctDirection) {
      return {
        particleId: particle.id,
        measuredSpeed: measuredSpeed,
        decision: shouldGoRight ? 'right' : 'left',
        timestamp: currentTime,
        bitValue: shouldGoRight ? 1 : 0
      };
    }

    return null;
  };

  // Gate control with realistic response time
  const controlGate = (measurement, currentTime) => {
    if (!measurement) return false;

    // Gate has finite response time
    if (currentTime - gateState.lastOperation < config.gateResponseTime * 1000) {
      return false; // Gate still responding to previous command
    }

    setGateState({
      open: true,
      lastOperation: currentTime,
      measurement: measurement
    });

    // Schedule gate closure
    setTimeout(() => {
      setGateState(prev => ({ ...prev, open: false }));
    }, config.gateResponseTime * 10); // Keep open for 5 picoseconds

    return true;
  };

  // Calculate chamber temperatures and entropies
  const calculateChamberProperties = (particles) => {
    const leftParticles = particles.filter(p => p.chamber === 'left');
    const rightParticles = particles.filter(p => p.chamber === 'right');

    const calculateTemperature = (chamberParticles) => {
      if (chamberParticles.length === 0) return 300;

      const totalKineticEnergy = chamberParticles.reduce((sum, p) => {
        const speed = getMolecularSpeed(p.vx, p.vy);
        return sum + 0.5 * molecularParams.mass * speed * speed;
      }, 0);

      // Temperature from equipartition theorem: <KE> = (f/2)kT, f=2 for 2D
      return totalKineticEnergy / (chamberParticles.length * kB);
    };

    const calculateEntropy = (chamberParticles, temperature) => {
      if (chamberParticles.length === 0) return 0;

      // Simplified entropy calculation using velocity distribution
      const speeds = chamberParticles.map(p => getMolecularSpeed(p.vx, p.vy));
      const meanSpeed = speeds.reduce((sum, speed) => sum + speed, 0) / speeds.length;
      const variance = speeds.reduce((sum, speed) => sum + Math.pow(speed - meanSpeed, 2), 0) / speeds.length;

      // Entropy proportional to log of phase space volume
      return chamberParticles.length * kB * Math.log(1 + variance / (meanSpeed * meanSpeed));
    };

    const leftTemp = calculateTemperature(leftParticles);
    const rightTemp = calculateTemperature(rightParticles);

    return {
      left: {
        temperature: leftTemp,
        entropy: calculateEntropy(leftParticles, leftTemp),
        particleCount: leftParticles.length
      },
      right: {
        temperature: rightTemp,
        entropy: calculateEntropy(rightParticles, rightTemp),
        particleCount: rightParticles.length
      }
    };
  };

  // Calculate Landauer cost and total energetics
  const calculateEnergetics = (memory, chambers) => {
    // Landauer cost: kBT ln(2) per bit erased
    const landauerCost = memory.length * kB * molecularParams.temperature * Math.log(2);

    // System entropy is sum of chamber entropies
    const systemEntropy = chambers.left.entropy + chambers.right.entropy;

    // Demon entropy from stored information
    const demonEntropy = memory.length * kB * Math.log(2);

    // Work potentially extractable from temperature difference
    const deltaT = Math.abs(chambers.left.temperature - chambers.right.temperature);
    const workExtracted = kB * deltaT * Math.log(2);

    // Total energy conservation check
    const totalEnergy = systemEntropy + demonEntropy;

    return {
      totalEnergy,
      systemEntropy,
      demonEntropy,
      landauerCost,
      workExtracted
    };
  };

  // Memory management and erasure
  const manageDemonMemory = (newMeasurement) => {
    setDemonMemory(prev => {
      let newMemory = [...prev];

      if (newMeasurement) {
        newMemory.push(newMeasurement);
      }

      // Erase old memories when buffer is full (Landauer cost incurred here)
      const maxMemorySize = 50;
      if (newMemory.length > maxMemorySize) {
        newMemory = newMemory.slice(-maxMemorySize);
      }

      return newMemory;
    });
  };

  // Main simulation step
  const simulationStep = useCallback(() => {
    const dt = config.timeStep; // femtoseconds

    setTime(t => t + dt);
    setRealTime(t => t + dt * 1e-15); // Convert to seconds

    setParticles(prevParticles => {
      const newParticles = prevParticles.map(particle => {
        // Update position with Verlet integration
        let newX = particle.x + particle.vx * dt * 1e-3; // Convert to pixel movement
        let newY = particle.y + particle.vy * dt * 1e-3;
        let newVx = particle.vx;
        let newVy = particle.vy;

        // Wall collisions with energy conservation
        const partitionX = config.chamberWidth / 2;
        const gateTop = config.chamberHeight / 2 - config.gateSize / 2;
        const gateBottom = config.chamberHeight / 2 + config.gateSize / 2;

        // Left and right walls
        if (newX <= 5 || newX >= config.chamberWidth - 5) {
          newVx = -newVx;
          newX = Math.max(5, Math.min(config.chamberWidth - 5, newX));
        }

        // Top and bottom walls
        if (newY <= 5 || newY >= config.chamberHeight - 5) {
          newVy = -newVy;
          newY = Math.max(5, Math.min(config.chamberHeight - 5, newY));
        }

        // Partition collision (unless gate is open and particle is in gate area)
        const inGateArea = newY >= gateTop && newY <= gateBottom;
        const atPartition = Math.abs(newX - partitionX) < config.partitionThickness / 2;

        if (atPartition && (!gateState.open || !inGateArea)) {
          newVx = -newVx;
          newX = newX < partitionX ? partitionX - config.partitionThickness / 2 - 1 : 
                                     partitionX + config.partitionThickness / 2 + 1;
        }

        // Update chamber assignment when passing through gate
        let newChamber = particle.chamber;
        if (gateState.open && inGateArea && atPartition) {
          newChamber = newX < partitionX ? 'left' : 'right';
        }

        return {
          ...particle,
          x: newX,
          y: newY,
          vx: newVx,
          vy: newVy,
          speed: getMolecularSpeed(newVx, newVy),
          chamber: newChamber
        };
      });

      // Demon operation
      if (config.demonEnabled) {
        newParticles.forEach(particle => {
          const measurement = demonMeasurement(particle, time);
          if (measurement) {
            const gateOpened = controlGate(measurement, time);
            if (gateOpened) {
              manageDemonMemory(measurement);
            }
          }
        });
      }

      return newParticles;
    });
  }, [config, time, gateState.open]);

  // Update derived quantities
  useEffect(() => {
    const chamberProps = calculateChamberProperties(particles);
    setChambers(chamberProps);

    const energeticProps = calculateEnergetics(demonMemory, chamberProps);
    setEnergetics(energeticProps);
  }, [particles, demonMemory]);

  // Animation loop
  useEffect(() => {
    if (isRunning) {
      animationRef.current = setInterval(simulationStep, 50); // 20 FPS
    } else {
      clearInterval(animationRef.current);
    }
    return () => clearInterval(animationRef.current);
  }, [isRunning, simulationStep]);

  // Initialize on mount
  useEffect(() => {
    initializeParticles();
  }, [initializeParticles]);

  // Canvas drawing
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw chamber boundaries
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 2;
    ctx.strokeRect(0, 0, config.chamberWidth, config.chamberHeight);

    // Draw partition
    const partitionX = config.chamberWidth / 2;
    ctx.fillStyle = '#666';
    ctx.fillRect(
      partitionX - config.partitionThickness / 2, 
      0, 
      config.partitionThickness, 
      config.chamberHeight
    );

    // Draw gate
    const gateTop = config.chamberHeight / 2 - config.gateSize / 2;
    const gateBottom = config.chamberHeight / 2 + config.gateSize / 2;

    if (gateState.open) {
      ctx.fillStyle = '#4CAF50';
      ctx.fillRect(
        partitionX - config.partitionThickness / 2, 
        gateTop, 
        config.partitionThickness, 
        config.gateSize
      );
    } else {
      ctx.strokeStyle = '#FFF';
      ctx.lineWidth = 1;
      ctx.strokeRect(
        partitionX - config.partitionThickness / 2, 
        gateTop, 
        config.partitionThickness, 
        config.gateSize
      );
    }

    // Draw particles with color coding by speed
    particles.forEach(particle => {
      ctx.beginPath();
      ctx.arc(particle.x, particle.y, particle.radius, 0, 2 * Math.PI);

      // Color by speed relative to mean speed
      const speedRatio = particle.speed / molecularParams.meanSpeed;
      if (speedRatio > 1.0) {
        ctx.fillStyle = `rgb(${Math.min(255, 150 + speedRatio * 50)}, 100, 100)`; // Red for fast
      } else {
        ctx.fillStyle = `rgb(100, 100, ${Math.min(255, 150 + (2-speedRatio) * 50)})`; // Blue for slow
      }

      ctx.fill();

      // Highlight measured particles
      if (demonMemory.some(m => m.particleId === particle.id && time - m.timestamp < 100)) {
        ctx.strokeStyle = '#FFD700';
        ctx.lineWidth = 2;
        ctx.stroke();
      }
    });

    // Draw temperature indicators
    ctx.fillStyle = '#FFF';
    ctx.font = '12px monospace';
    ctx.fillText(`L: ${chambers.left.temperature.toFixed(1)}K`, 10, 20);
    ctx.fillText(`R: ${chambers.right.temperature.toFixed(1)}K`, config.chamberWidth - 80, 20);

  }, [particles, gateState, chambers, config, demonMemory, time]);

  const reset = () => {
    setIsRunning(false);
    setTime(0);
    setRealTime(0);
    initializeParticles();
  };

  const exportData = () => {
    const data = {
      time: realTime,
      chambers,
      energetics,
      demonMemory: demonMemory.length,
      config,
      molecularParams
    };

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `maxwell_demon_${Date.now()}.json`;
    a.click();
  };

  return (
    <div className="max-w-7xl mx-auto p-6 bg-gray-900 text-white min-h-screen">
      <div className="mb-6">
        <h1 className="text-3xl font-bold mb-2">Maxwell's Demon: Physically Accurate Simulation</h1>
        <p className="text-gray-300">
          Faithful implementation with N₂ molecules, Maxwell-Boltzmann statistics, and proper thermodynamic accounting
        </p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Main Simulation Canvas */}
        <div className="lg:col-span-2">
          <div className="bg-gray-800 rounded-lg p-4">
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-xl font-semibold">Maxwell's Demon Simulation</h2>
              <div className="flex gap-2">
                <button
                  onClick={() => setIsRunning(!isRunning)}
                  className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 rounded"
                >
                  {isRunning ? <Pause size={16} /> : <Play size={16} />}
                  {isRunning ? 'Pause' : 'Play'}
                </button>
                <button
                  onClick={reset}
                  className="flex items-center gap-2 px-4 py-2 bg-gray-600 hover:bg-gray-700 rounded"
                >
                  <RotateCcw size={16} />
                  Reset
                </button>
                <button
                  onClick={exportData}
                  className="flex items-center gap-2 px-4 py-2 bg-green-600 hover:bg-green-700 rounded"
                >
                  <Download size={16} />
                  Export
                </button>
              </div>
            </div>

            <div className="bg-white rounded mb-4">
              <canvas
                ref={canvasRef}
                width={config.chamberWidth}
                height={config.chamberHeight}
                className="border border-gray-300"
              />
            </div>

            {/* Real-time Status */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
              <div className="bg-gray-700 p-3 rounded">
                <div className="text-gray-400">Physical Time</div>
                <div className="text-lg font-mono">{(realTime * 1e12).toFixed(1)} ps</div>
              </div>
              <div className="bg-gray-700 p-3 rounded">
                <div className="text-gray-400">Gate State</div>
                <div className={`text-lg font-mono ${gateState.open ? 'text-green-400' : 'text-red-400'}`}>
                  {gateState.open ? 'OPEN' : 'CLOSED'}
                </div>
              </div>
              <div className="bg-gray-700 p-3 rounded">
                <div className="text-gray-400">ΔT (K)</div>
                <div className="text-lg font-mono">
                  {Math.abs(chambers.left.temperature - chambers.right.temperature).toFixed(2)}
                </div>
              </div>
              <div className="bg-gray-700 p-3 rounded">
                <div className="text-gray-400">Demon Memory</div>
                <div className="text-lg font-mono">{demonMemory.length} bits</div>
              </div>
            </div>
          </div>
        </div>

        {/* Controls and Data */}
        <div className="space-y-6">
          {/* Configuration */}
          <div className="bg-gray-800 rounded-lg p-4">
            <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
              <Settings size={16} />
              Demon Configuration
            </h3>

            <div className="space-y-4">
              <div className="flex items-center gap-2">
                <input
                  type="checkbox"
                  id="demonEnabled"
                  checked={config.demonEnabled}
                  onChange={(e) => setConfig(prev => ({ ...prev, demonEnabled: e.target.checked }))}
                />
                <label htmlFor="demonEnabled" className="text-sm">Enable Demon</label>
              </div>

              <div>
                <label className="block text-sm font-medium mb-2">
                  Particles: {config.numParticles}
                </label>
                <input
                  type="range"
                  min="100"
                  max="500"
                  value={config.numParticles}
                  onChange={(e) => setConfig(prev => ({ ...prev, numParticles: parseInt(e.target.value) }))}
                  className="w-full"
                />
              </div>

              <div>
                <label className="block text-sm font-medium mb-2">
                  Measurement Error: {(config.measurementPrecision * 100).toFixed(1)}%
                </label>
                <input
                  type="range"
                  min="0.01"
                  max="0.2"
                  step="0.01"
                  value={config.measurementPrecision}
                  onChange={(e) => setConfig(prev => ({ ...prev, measurementPrecision: parseFloat(e.target.value) }))}
                  className="w-full"
                />
              </div>

              <div>
                <label className="block text-sm font-medium mb-2">
                  Gate Response: {config.gateResponseTime} ps
                </label>
                <input
                  type="range"
                  min="0.1"
                  max="2.0"
                  step="0.1"
                  value={config.gateResponseTime}
                  onChange={(e) => setConfig(prev => ({ ...prev, gateResponseTime: parseFloat(e.target.value) }))}
                  className="w-full"
                />
              </div>
            </div>
          </div>

          {/* Thermodynamic Analysis */}
          <div className="bg-gray-800 rounded-lg p-4">
            <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
              <Thermometer size={16} />
              Thermodynamics
            </h3>
            <div className="space-y-3">
              <div className="flex justify-between">
                <span className="text-gray-400">Left Chamber:</span>
                <span className="font-mono">{chambers.left.temperature.toFixed(2)} K</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-400">Right Chamber:</span>
                <span className="font-mono">{chambers.right.temperature.toFixed(2)} K</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-400">System Entropy:</span>
                <span className="font-mono">{(energetics.systemEntropy / kB).toFixed(2)} kB</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-400">Demon Entropy:</span>
                <span className="font-mono">{(energetics.demonEntropy / kB).toFixed(2)} kB</span>
              </div>
              <div className="flex justify-between font-semibold border-t border-gray-600 pt-2">
                <span>Total Entropy:</span>
                <span className="font-mono">
                  {((energetics.systemEntropy + energetics.demonEntropy) / kB).toFixed(2)} kB
                </span>
              </div>
            </div>
          </div>

          {/* Energy Analysis */}
          <div className="bg-gray-800 rounded-lg p-4">
            <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
              <Zap size={16} />
              Energy & Information
            </h3>
            <div className="space-y-2">
              <div className="flex justify-between">
                <span className="text-gray-400">Landauer Cost:</span>
                <span className="font-mono">{(energetics.landauerCost / kB / molecularParams.temperature).toFixed(3)} kBT</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-400">Work Available:</span>
                <span className="font-mono">{(energetics.workExtracted / kB / molecularParams.temperature).toFixed(3)} kBT</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-400">Efficiency:</span>
                <span className="font-mono">
                  {energetics.landauerCost > 0 ? 
                    ((energetics.workExtracted / energetics.landauerCost) * 100).toFixed(1) : 0}%
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-400">Net Energy:</span>
                <span className={`font-mono ${energetics.landauerCost >= energetics.workExtracted ? 'text-green-400' : 'text-red-400'}`}>
                  {((energetics.landauerCost - energetics.workExtracted) / kB / molecularParams.temperature).toFixed(3)} kBT
                </span>
              </div>
            </div>
          </div>

          {/* Information Panel */}
          <div className="bg-gray-800 rounded-lg p-4">
            <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
              <Info size={16} />
              Physical Parameters
            </h3>
            <div className="text-sm text-gray-300 space-y-2">
              <p><strong>Molecule:</strong> N₂ (nitrogen)</p>
              <p><strong>Mass:</strong> 28.014 amu</p>
              <p><strong>Diameter:</strong> 3.8 Å</p>
              <p><strong>Mean Speed:</strong> {(molecularParams.meanSpeed).toFixed(0)} m/s</p>
              <p><strong>Gate Size:</strong> ~3 nm (8× molecular diameter)</p>
              <p><strong>Response Time:</strong> {config.gateResponseTime} ps</p>
              <p><strong>Chamber Size:</strong> ~50 × 37.5 nm</p>
              <div className="mt-3 pt-2 border-t border-gray-600">
                <p><strong>Red particles:</strong> Speed > mean (fast)</p>
                <p><strong>Blue particles:</strong> Speed < mean (slow)</p>
                <p><strong>Gold outline:</strong> Recently measured</p>
                <p><strong>Green gate:</strong> Demon-controlled opening</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Simulator;

