import React, { useState, useEffect, useRef, useMemo } from 'react';
import * as THREE from 'three';

const OptimalTilingFramework = () => {
  const mountRef = useRef(null);
  const sceneRef = useRef(null);
  const rendererRef = useRef(null);
  const cameraRef = useRef(null);
  const groupRef = useRef(null);
  const animationRef = useRef(null);

  // Core parameters
  const [params, setParams] = useState({
    kExp: 1,
    kMul: 1,
    kDiv: 1,
    kScale: 1,
    scaleIndex: 3, // Index into extended scale array
    tileDepth: 3,
    rotationSpeed: 0,
    showAnalysis: true,
    useOptimalK: false, // Use k = τ^(-1)
    enableCurvedSurface: false,
    curvature: 0,
    renderMode: 'both' // 'wireframe', 'filled', 'both'
  });

  // Extended scale hierarchy
  const scaleHierarchy = useMemo(() => {
    const tau = 2 * Math.PI;
    const optimalK = params.useOptimalK ? 1 / tau : params.kScale;

    return [
      optimalK / Math.sqrt(2),
      optimalK / Math.sqrt(5),
      optimalK / Math.sqrt(10),
      optimalK * Math.sqrt(1),
      optimalK * Math.sqrt(2),
      optimalK * Math.sqrt(5),
      optimalK * Math.sqrt(10)
    ];
  }, [params.kScale, params.useOptimalK]);

  // Base geometric construction coordinates
  const baseCoords = {
    // Triangle ABC
    A: [-1, -1], B: [-1, 2], C: [3, -1],
    // Triangle DEF  
    D: [-1, 1], E: [2, 1], F: [-1, -3],
    // Triangle GHI
    G: [1, 1], H: [1, -2], I: [-3, 1],
    // Triangle JKL
    J: [1, -1], K: [-2, -1], L: [1, 3],
    // Square MNOP
    M: [-1.4, -0.2], N: [-0.2, 1.4], O: [1.4, 0.2], P: [0.2, -1.4]
  };

  // Calculate theta based on parameters
  const theta = useMemo(() => {
    const tau = 2 * Math.PI;
    return (Math.pow(tau, params.kExp) * params.kMul) / params.kDiv;
  }, [params.kExp, params.kMul, params.kDiv]);

  // Transform coordinates (rotate + scale)
  const transformCoords = (coords, scale, rotation, offset = [0, 0]) => {
    const cos = Math.cos(rotation);
    const sin = Math.sin(rotation);

    return [
      scale * (coords[0] * cos - coords[1] * sin) + offset[0],
      scale * (coords[0] * sin + coords[1] * cos) + offset[1]
    ];
  };

  // Generate tiling pattern recursively
  const generateTiling = (depth, currentScale, currentOffset = [0, 0], level = 0) => {
    if (level >= depth) return [];

    const tiles = [];
    const tileSpacing = 2.5 * currentScale;
    const nextScale = currentScale * scaleHierarchy[params.scaleIndex] / scaleHierarchy[3]; // Relative scaling

    // Generate base pattern at current level
    const basePattern = createBasePattern(currentScale, currentOffset);
    tiles.push(...basePattern);

    // Recursive subdivision if depth allows
    if (level < depth - 1) {
      const gridSize = Math.max(1, Math.floor(4 - level)); // Adaptive grid size

      for (let i = -gridSize; i <= gridSize; i++) {
        for (let j = -gridSize; j <= gridSize; j++) {
          if (i === 0 && j === 0) continue; // Skip center (already covered)

          const newOffset = [
            currentOffset[0] + i * tileSpacing,
            currentOffset[1] + j * tileSpacing
          ];

          tiles.push(...generateTiling(depth, nextScale, newOffset, level + 1));
        }
      }
    }

    return tiles;
  };

  // Create base pattern at given scale and offset
  const createBasePattern = (scale, offset) => {
    const patterns = [];

    // Transform all base coordinates
    const transformed = {};
    Object.keys(baseCoords).forEach(key => {
      transformed[key] = transformCoords(baseCoords[key], scale, theta, offset);
    });

    // Define triangles and square
    const shapes = [
      { points: [transformed.A, transformed.B, transformed.C], color: 0xff4444, name: 'ABC' },
      { points: [transformed.D, transformed.E, transformed.F], color: 0xff8844, name: 'DEF' },
      { points: [transformed.G, transformed.H, transformed.I], color: 0x44ff44, name: 'GHI' },
      { points: [transformed.J, transformed.K, transformed.L], color: 0x4444ff, name: 'JKL' },
      { points: [transformed.M, transformed.N, transformed.O, transformed.P], color: 0x8844ff, name: 'MNOP' }
    ];

    patterns.push(...shapes);
    return patterns;
  };

  // Apply curvature transformation
  const applyCurvature = (point, curvature) => {
    if (curvature === 0) return point;

    const r = Math.sqrt(point[0] * point[0] + point[1] * point[1]);
    const factor = 1 + curvature * r * r * 0.01;

    return [
      point[0],
      point[1], 
      curvature * r * r * 0.1 // Z displacement for curvature
    ];
  };

  // Create Three.js geometry from pattern
  const createGeometry = (patterns) => {
    if (!groupRef.current) return;

    // Clear existing geometry
    while (groupRef.current.children.length > 0) {
      const child = groupRef.current.children[0];
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
      groupRef.current.remove(child);
    }

    patterns.forEach((pattern, index) => {
      const { points, color } = pattern;

      // Apply curvature if enabled
      const curvedPoints = points.map(p => 
        applyCurvature(p, params.enableCurvedSurface ? params.curvature : 0)
      );

      // Create filled geometry
      if (params.renderMode === 'filled' || params.renderMode === 'both') {
        const shape = new THREE.Shape();
        if (curvedPoints.length > 0) {
          const firstPoint = curvedPoints[0];
          shape.moveTo(firstPoint[0], firstPoint[1]);

          for (let i = 1; i < curvedPoints.length; i++) {
            shape.lineTo(curvedPoints[i][0], curvedPoints[i][1]);
          }
          shape.lineTo(firstPoint[0], firstPoint[1]);
        }

        const geometry = new THREE.ShapeGeometry(shape);
        const material = new THREE.MeshBasicMaterial({ 
          color, 
          transparent: true, 
          opacity: 0.7,
          side: THREE.DoubleSide
        });

        const mesh = new THREE.Mesh(geometry, material);
        if (params.enableCurvedSurface) {
          // Apply Z displacement for curvature
          const positions = geometry.attributes.position.array;
          for (let i = 0; i < positions.length; i += 3) {
            const x = positions[i];
            const y = positions[i + 1];
            const r = Math.sqrt(x * x + y * y);
            positions[i + 2] = params.curvature * r * r * 0.1;
          }
          geometry.attributes.position.needsUpdate = true;
        }

        groupRef.current.add(mesh);
      }

      // Create wireframe
      if (params.renderMode === 'wireframe' || params.renderMode === 'both') {
        const wireframeGeometry = new THREE.BufferGeometry();
        const vertices = [];

        for (let i = 0; i < curvedPoints.length; i++) {
          const current = curvedPoints[i];
          const next = curvedPoints[(i + 1) % curvedPoints.length];

          vertices.push(current[0], current[1], current[2] || 0);
          vertices.push(next[0], next[1], next[2] || 0);
        }

        wireframeGeometry.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));

        const wireframeMaterial = new THREE.LineBasicMaterial({ 
          color: 0x000000, 
          linewidth: 2 
        });

        const wireframe = new THREE.LineSegments(wireframeGeometry, wireframeMaterial);
        groupRef.current.add(wireframe);
      }
    });
  };

  // Calculate geometric properties for analysis
  const analyzePattern = (patterns) => {
    let totalArea = 0;
    let totalPerimeter = 0;
    const areas = [];

    patterns.forEach(pattern => {
      const { points } = pattern;

      // Calculate area using shoelace formula
      let area = 0;
      for (let i = 0; i < points.length; i++) {
        const j = (i + 1) % points.length;
        area += points[i][0] * points[j][1];
        area -= points[j][0] * points[i][1];
      }
      area = Math.abs(area) / 2;
      areas.push(area);
      totalArea += area;

      // Calculate perimeter
      let perimeter = 0;
      for (let i = 0; i < points.length; i++) {
        const j = (i + 1) % points.length;
        const dx = points[j][0] - points[i][0];
        const dy = points[j][1] - points[i][1];
        perimeter += Math.sqrt(dx * dx + dy * dy);
      }
      totalPerimeter += perimeter;
    });

    return { totalArea, totalPerimeter, areas, patternCount: patterns.length };
  };

