  const groupRef = useRef(null);
  const animationRef = useRef(null);

  // Core parameters
  const [params, setParams] = useState({
    kExp: 1,
    kMul: 1,
    kDiv: 1,
    kScale: 1,
    useOptimalK: false, // Use k = τ^(-1)

    // Scale hierarchy controls
    scaleOctaves: 2, // How many scale octaves to show (both directions)
    baseScales: 4, // How many base scales to use (√1, √2, √5, √10)

    // Tiling controls
    tileExtent: 3, // How far to tile across the plane
    showScaleLevel: 'all', // 'all', 'single', or specific level

    // Performance controls
    maxTiles: 10000,
    lodThreshold: 50, // Level of detail threshold

    // Visual controls
    rotationSpeed: 0,
    showAnalysis: true,
    enableCurvedSurface: false,
    curvature: 0,
    renderMode: 'both', // 'wireframe', 'filled', 'both'

    // Perfect square viewport
    viewportSize: 20 // Size of the square viewport
  });

  // Generate infinite scale hierarchy
  const scaleHierarchy = useMemo(() => {
    const tau = 2 * Math.PI;
    const k = params.useOptimalK ? 1 / tau : params.kScale;

    const baseFactors = [1, 2, 5, 10]; // √1, √2, √5, √10
    const scales = [];

    // Generate scales from smallest to largest
    for (let octave = -params.scaleOctaves; octave <= params.scaleOctaves; octave++) {
      const octaveMultiplier = Math.pow(10, octave);

      baseFactors.slice(0, params.baseScales).forEach(factor => {
        if (octave < 0) {
          // Smaller scales: k/√(factor * 10^|octave|)
          scales.push({
            value: k / Math.sqrt(factor * Math.pow(10, Math.abs(octave))),
            octave,
            factor,
            label: `k/√${factor * Math.pow(10, Math.abs(octave))}`
          });
        } else {
          // Larger scales: k√(factor * 10^octave)
          scales.push({
            value: k * Math.sqrt(factor * octaveMultiplier),
            octave,
            factor,
            label: octave === 0 ? `k√${factor}` : `${octaveMultiplier}k√${factor}`
          });
        }
      });
    }

    return scales.sort((a, b) => a.value - b.value);
  }, [params.kScale, params.useOptimalK, params.scaleOctaves, params.baseScales]);

  // Base geometric construction coordinates
  const baseCoords = {
    // Triangle ABC
    A: [-1, -1], B: [-1, 2], C: [3, -1],
    // Triangle DEF  
    D: [-1, 1], E: [2, 1], F: [-1, -3],
    // Triangle GHI
    G: [1, 1], H: [1, -2], I: [-3, 1],
    // Triangle JKL
    J: [1, -1], K: [-2, -1], L: [1, 3],
    // Square MNOP
    M: [-1.4, -0.2], N: [-0.2, 1.4], O: [1.4, 0.2], P: [0.2, -1.4]
  };

  // Calculate theta based on parameters
  const theta = useMemo(() => {
    const tau = 2 * Math.PI;
    return (Math.pow(tau, params.kExp) * params.kMul) / params.kDiv;
  }, [params.kExp, params.kMul, params.kDiv]);

  // Transform coordinates (rotate + scale)
  const transformCoords = (coords, scale, rotation, offset = [0, 0]) => {
    const cos = Math.cos(rotation);
    const sin = Math.sin(rotation);

    return [
      scale * (coords[0] * cos - coords[1] * sin) + offset[0],
      scale * (coords[0] * sin + coords[1] * cos) + offset[1]
    ];
  };

  // Generate complete tiling pattern across all scales
  const generateAllScales = () => {
    const allPatterns = [];
    let totalTiles = 0;

    scaleHierarchy.forEach((scaleInfo, scaleIndex) => {
      if (totalTiles >= params.maxTiles) return;

      const scale = scaleInfo.value;
