      // Generate tiling grid for this scale
      for (let i = -adaptiveExtent; i <= adaptiveExtent; i++) {
        for (let j = -adaptiveExtent; j <= adaptiveExtent; j++) {
          if (totalTiles >= params.maxTiles) break;

          const offset = [i * tileSpacing, j * tileSpacing];
          const patterns = createBasePattern(scale, offset, scaleInfo);

          // Level of detail: simplify distant or very small patterns
          const distance = Math.sqrt(i * i + j * j);
          if (distance > params.lodThreshold || scale < 0.001) {
            // Skip or simplify very distant/small patterns
            continue;
          }

          allPatterns.push(...patterns);
          totalTiles += patterns.length;
        }
        if (totalTiles >= params.maxTiles) break;
