    const transformed = {};
    Object.keys(baseCoords).forEach(key => {
      transformed[key] = transformCoords(baseCoords[key], scale, theta, offset);
    });

    // Define triangles and square with scale information
    const shapes = [
      { 
        points: [transformed.A, transformed.B, transformed.C], 
        color: 0xff4444, 
        name: 'ABC',
        scale: scaleInfo,
        opacity: Math.min(1, scale * 2) // Fade very small scales
      },
      { 
        points: [transformed.D, transformed.E, transformed.F], 
