    const r = Math.sqrt(point[0] * point[0] + point[1] * point[1]);
    const factor = 1 + curvature * r * r * 0.01;

    return [
      point[0],
      point[1], 
      curvature * r * r * 0.1 // Z displacement for curvature
    ];
