          shape.moveTo(firstPoint[0], firstPoint[1]);

          for (let i = 1; i < curvedPoints.length; i++) {
            shape.lineTo(curvedPoints[i][0], curvedPoints[i][1]);
          }
          shape.lineTo(firstPoint[0], firstPoint[1]);
