  }, [params.viewportSize]);

  // Update pattern when parameters change
  useEffect(() => {
    if (!groupRef.current) return;

    const patterns = generateAllScales();
    createGeometry(patterns);

    console.log(`Generated ${patterns.length} patterns across ${scaleHierarchy.length} scales`);
  }, [params, theta, scaleHierarchy]);

  // Animation loop
  useEffect(() => {
    const animate = () => {
      if (params.rotationSpeed !== 0 && groupRef.current) {
        groupRef.current.rotation.z += params.rotationSpeed * 0.01;
      }

