            </div>
          </div>
        </div>

        {/* Tiling & Performance */}
        <div className="mb-6">
          <h3 className="font-semibold mb-2 text-gray-700">Tiling & Performance</h3>
          <div className="space-y-2">
            <div>
              <label className="block text-sm">Tile Extent: {params.tileExtent}</label>
              <input
                type="range"
                min="1"
                max="8"
                step="1"
