                className="w-full"
              />
            </div>
            <div>
              <label className="block text-sm">Max Tiles: {params.maxTiles}</label>
              <input
                type="range"
                min="1000"
                max="50000"
                step="1000"
                value={params.maxTiles}
                onChange={(e) => setParams(p => ({ ...p, maxTiles: parseInt(e.target.value) }))}
                className="w-full"
              />
            </div>
            <div>
              <label className="block text-sm">LOD Threshold: {params.lodThreshold}</label>
              <input
                type="range"
                min="10"
                max="200"
                step="10"
                value={params.lodThreshold}
                onChange={(e) => setParams(p => ({ ...p, lodThreshold: parseInt(e.target.value) }))}
                className="w-full"
              />
            </div>
          </div>
        </div>

        {/* Visual Controls */}
        <div className="mb-6">
          <h3 className="font-semibold mb-2 text-gray-700">Visual</h3>
          <div className="space-y-2">
            <div>
              <label className="block text-sm">Viewport Size: {params.viewportSize}</label>
              <input
                type="range"
                min="5"
                max="50"
                step="5"
                value={params.viewportSize}
                onChange={(e) => setParams(p => ({ ...p, viewportSize: parseInt(e.target.value) }))}
                className="w-full"
              />
            </div>
            <div>
              <label className="block text-sm">Rotation Speed: {params.rotationSpeed}</label>
              <input
                type="range"
                min="-3"
                max="3"
                step="0.1"
                value={params.rotationSpeed}
                onChange={(e) => setParams(p => ({ ...p, rotationSpeed: parseFloat(e.target.value) }))}
                className="w-full"
              />
            </div>
            <div>
              <label className="flex items-center">
                <input
                  type="checkbox"
                  checked={params.enableCurvedSurface}
                  onChange={(e) => setParams(p => ({ ...p, enableCurvedSurface: e.target.checked }))}
                  className="mr-2"
                />
                Curved Surface
              </label>
            </div>
            {params.enableCurvedSurface && (
              <div>
                <label className="block text-sm">Curvature: {params.curvature}</label>
                <input
                  type="range"
                  min="-1"
                  max="1"
                  step="0.1"
                  value={params.curvature}
                  onChange={(e) => setParams(p => ({ ...p, curvature: parseFloat(e.target.value) }))}
                  className="w-full"
                />
              </div>
            )}
          </div>
        </div>

        {/* Analysis */}
        <div className="mb-6">
          <h3 className="font-semibold mb-2 text-gray-700">Analysis</h3>
          <div className="text-sm space-y-1">
            <div>Active Scales: {scaleHierarchy.length}</div>
            <div>θ = {theta.toFixed(4)} rad</div>
            <div>θ/τ = {(theta / (2 * Math.PI)).toFixed(4)}</div>
            <div>k = {params.useOptimalK ? (1 / (2 * Math.PI)).toFixed(6) : params.kScale}</div>
            <div className="text-xs text-gray-500 mt-2">
              Scale range: {scaleHierarchy[0]?.value.toFixed(6)} to {scaleHierarchy[scaleHierarchy.length - 1]?.value.toFixed(3)}
            </div>
          </div>
        </div>
      </div>

      {/* Perfect Square 3D Visualization */}
      <div className="flex-1 flex flex-col items-center justify-center bg-gray-50">
        <div ref={mountRef} className="border-2 border-gray-300" />

        {/* Scale Legend */}
        <div className="mt-4 bg-white p-3 rounded shadow text-sm max-w-md">
          <div className="font-semibold mb-2">Scale Hierarchy ({scaleHierarchy.length} levels)</div>
          <div className="grid grid-cols-2 gap-1 text-xs">
            {scaleHierarchy.slice(0, 8).map((scale, i) => (
              <div key={i} className="truncate">
                {scale.label}: {scale.value.toFixed(4)}
              </div>
            ))}
            {scaleHierarchy.length > 8 && <div className="col-span-2 text-gray-500">...and {scaleHierarchy.length - 8} more</div>}
          </div>
          {params.useOptimalK && <div className="text-blue-600 font-medium mt-2">Using Optimal τ⁻¹ Scaling</div>}
        </div>
      </div>
    </div>
  );
};

export default OptimalTilingFramework;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import * as THREE from 'three';

const OptimalTilingFramework = () => {
  const mountRef = useRef(null);
  const sceneRef = useRef(null);
  const rendererRef = useRef(null);
  const cameraRef = useRef(null);
  const groupRef = useRef(null);
  const animationRef = useRef(null);

  // Core parameters
  const [params, setParams] = useState({
    kExp: 1,
    kMul: 1,
    kDiv: 1,
    kScale: 1,
    useOptimalK: false, // Use k = τ^(-1)

    // Scale hierarchy controls
    scaleOctaves: 2, // How many scale octaves to show (both directions)
    baseScales: 4, // How many base scales to use (√1, √2, √5, √10)

    // Tiling mode
    tilingMode: 'hierarchical', // 'hierarchical', 'uniform', 'base-only'

    // Tiling controls
    tileExtent: 3, // How far to tile across the plane
    hierarchicalDepth: 4, // How many hierarchical levels

    // Performance controls
    maxTiles: 15000,

    // Visual controls
    rotationSpeed: 0,
    showAnalysis: true,
    enableCurvedSurface: false,
    curvature: 0,
    renderMode: 'both', // 'wireframe', 'filled', 'both'
    showBaseConstruction: false, // Show just the connected base pattern

    // Perfect square viewport
    viewportSize: 20 // Size of the square viewport
  });

  // Generate infinite scale hierarchy
  const scaleHierarchy = useMemo(() => {
    const tau = 2 * Math.PI;
    const k = params.useOptimalK ? 1 / tau : params.kScale;

    const baseFactors = [1, 2, 5, 10]; // √1, √2, √5, √10
    const scales = [];

    // Generate scales from smallest to largest
    for (let octave = -params.scaleOctaves; octave <= params.scaleOctaves; octave++) {
      const octaveMultiplier = Math.pow(10, octave);

      baseFactors.slice(0, params.baseScales).forEach(factor => {
        if (octave < 0) {
          // Smaller scales: k/√(factor * 10^|octave|)
          scales.push({
            value: k / Math.sqrt(factor * Math.pow(10, Math.abs(octave))),
            octave,
            factor,
            label: `k/√${factor * Math.pow(10, Math.abs(octave))}`
          });
        } else {
          // Larger scales: k√(factor * 10^octave)
          scales.push({
            value: k * Math.sqrt(factor * octaveMultiplier),
            octave,
            factor,
            label: octave === 0 ? `k√${factor}` : `${octaveMultiplier}k√${factor}`
          });
        }
      });
    }

    return scales.sort((a, b) => a.value - b.value);
  }, [params.kScale, params.useOptimalK, params.scaleOctaves, params.baseScales]);

  // Base geometric construction coordinates
  const baseCoords = {
    // Triangle ABC
    A: [-1, -1], B: [-1, 2], C: [3, -1],
    // Triangle DEF  
    D: [-1, 1], E: [2, 1], F: [-1, -3],
    // Triangle GHI
    G: [1, 1], H: [1, -2], I: [-3, 1],
    // Triangle JKL
    J: [1, -1], K: [-2, -1], L: [1, 3],
    // Square MNOP
    M: [-1.4, -0.2], N: [-0.2, 1.4], O: [1.4, 0.2], P: [0.2, -1.4]
  };

  // Calculate theta based on parameters
  const theta = useMemo(() => {
    const tau = 2 * Math.PI;
    return (Math.pow(tau, params.kExp) * params.kMul) / params.kDiv;
  }, [params.kExp, params.kMul, params.kDiv]);

  // Transform coordinates (rotate + scale)
  const transformCoords = (coords, scale, rotation, offset = [0, 0]) => {
    const cos = Math.cos(rotation);
    const sin = Math.sin(rotation);

    return [
      scale * (coords[0] * cos - coords[1] * sin) + offset[0],
      scale * (coords[0] * sin + coords[1] * cos) + offset[1]
    ];
  };

  // Generate base construction only
  const generateBaseConstruction = () => {
    const scale = scaleHierarchy[Math.floor(scaleHierarchy.length / 2)]?.value || 1;

    // Transform all base coordinates
    const transformed = {};
    Object.keys(baseCoords).forEach(key => {
      transformed[key] = transformCoords(baseCoords[key], scale, theta, [0, 0]);
    });

    if (params.showBaseConstruction) {
      // Return the connected outline polygon
      return [{
        points: [
          transformed.A, transformed.K, transformed.M, transformed.I,
          transformed.D, transformed.B, transformed.N, transformed.L,
          transformed.G, transformed.E, transformed.O, transformed.C,
          transformed.J, transformed.H, transformed.P, transformed.F
        ],
        color: 0x333333,
        name: 'BaseConstruction',
        opacity: 0.3,
        isBaseConstruction: true
      }];
    } else {
      // Return individual shapes
      return [
        { points: [transformed.A, transformed.B, transformed.C], color: 0xff4444, name: 'ABC', opacity: 0.7 },
        { points: [transformed.D, transformed.E, transformed.F], color: 0xff8844, name: 'DEF', opacity: 0.7 },
        { points: [transformed.G, transformed.H, transformed.I], color: 0x44ff44, name: 'GHI', opacity: 0.7 },
        { points: [transformed.J, transformed.K, transformed.L], color: 0x4444ff, name: 'JKL', opacity: 0.7 },
        { points: [transformed.M, transformed.N, transformed.O, transformed.P], color: 0x8844ff, name: 'MNOP', opacity: 0.7 }
      ];
    }
  };

  // Generate hierarchical tiling with proper coverage
  const generateHierarchicalTiling = () => {
    if (params.tilingMode === 'base-only') {
      return generateBaseConstruction();
    }

    const patterns = [];
    let totalTiles = 0;

    // Sort scales from largest to smallest for hierarchical filling
    const sortedScales = [...scaleHierarchy].reverse();

    for (let level = 0; level < Math.min(params.hierarchicalDepth, sortedScales.length); level++) {
      if (totalTiles >= params.maxTiles) break;

      const scaleInfo = sortedScales[level];
      const scale = scaleInfo.value;
      const tileSpacing = 2.5 * scale;

      // Calculate coverage area based on viewport and previous levels
      const coverageRadius = params.viewportSize / 2;
      const tilesNeeded = Math.ceil(coverageRadius / tileSpacing);

      // Reduce extent for smaller scales to fill gaps, not overlap
      const adaptiveExtent = level === 0 ? tilesNeeded : 
        Math.max(1, Math.floor(tilesNeeded / Math.pow(1.5, level)));

      // Generate grid for this hierarchical level
      for (let i = -adaptiveExtent; i <= adaptiveExtent; i++) {
        for (let j = -adaptiveExtent; j <= adaptiveExtent; j++) {
          if (totalTiles >= params.maxTiles) break;

          const offset = [i * tileSpacing, j * tileSpacing];

          // Skip if this position would be covered by a larger scale
          // (This creates the gap-filling effect)
          if (level > 0 && shouldSkipPosition(offset, sortedScales, level)) {
            continue;
          }

          const newPatterns = createBasePattern(scale, offset, scaleInfo, level);
          patterns.push(...newPatterns);
          totalTiles += newPatterns.length;
        }
        if (totalTiles >= params.maxTiles) break;
      }
    }

    return patterns;
  };

  // Check if a position should be skipped due to larger scale coverage
  const shouldSkipPosition = (position, sortedScales, currentLevel) => {
    const [x, y] = position;

    // Check against larger scales (previous levels)
    for (let prevLevel = 0; prevLevel < currentLevel; prevLevel++) {
      const prevScale = sortedScales[prevLevel].value;
      const prevSpacing = 2.5 * prevScale;
      const prevExtent = Math.ceil((params.viewportSize / 2) / prevSpacing);

      // Check if this position is close to a larger scale tile center
      for (let i = -prevExtent; i <= prevExtent; i++) {
        for (let j = -prevExtent; j <= prevExtent; j++) {
          const prevCenter = [i * prevSpacing, j * prevSpacing];
          const distance = Math.sqrt(
            Math.pow(x - prevCenter[0], 2) + Math.pow(y - prevCenter[1], 2)
          );

          // If too close to a larger tile, skip this position
          if (distance < prevSpacing * 0.8) {
            return true;
          }
        }
      }
    }

    return false;
  };

  // Generate uniform tiling (all scales)
  const generateUniformTiling = () => {
    const patterns = [];
    let totalTiles = 0;

    scaleHierarchy.forEach((scaleInfo, scaleIndex) => {
      if (totalTiles >= params.maxTiles) return;

      const scale = scaleInfo.value;
      const tileSpacing = 2.5 * scale;

      // Adaptive extent based on scale size
      const adaptiveExtent = Math.max(1, Math.min(params.tileExtent, 
        Math.floor((params.viewportSize / 2) / tileSpacing * 0.7)));

      // Generate tiling grid for this scale
      for (let i = -adaptiveExtent; i <= adaptiveExtent; i++) {
        for (let j = -adaptiveExtent; j <= adaptiveExtent; j++) {
          if (totalTiles >= params.maxTiles) break;

          const offset = [i * tileSpacing, j * tileSpacing];
          const newPatterns = createBasePattern(scale, offset, scaleInfo);

          patterns.push(...newPatterns);
          totalTiles += newPatterns.length;
        }
        if (totalTiles >= params.maxTiles) break;
      }
    });

    return patterns;
  };

  // Create base pattern at given scale and offset
  const createBasePattern = (scale, offset, scaleInfo, level = 0) => {
    const patterns = [];

    // Transform all base coordinates
    const transformed = {};
    Object.keys(baseCoords).forEach(key => {
      transformed[key] = transformCoords(baseCoords[key], scale, theta, offset);
    });

    // Opacity based on scale and level
    const opacity = Math.min(1, Math.max(0.2, scale * 3)) * (1 - level * 0.1);

    // Define triangles and square with scale information
    const shapes = [
      { 
        points: [transformed.A, transformed.B, transformed.C], 
        color: 0xff4444, 
        name: 'ABC',
        scale: scaleInfo,
        opacity: opacity,
        level: level
      },
      { 
        points: [transformed.D, transformed.E, transformed.F], 
        color: 0xff8844, 
        name: 'DEF',
        scale: scaleInfo,
        opacity: opacity,
        level: level
      },
      { 
        points: [transformed.G, transformed.H, transformed.I], 
        color: 0x44ff44, 
        name: 'GHI',
        scale: scaleInfo,
        opacity: opacity,
        level: level
      },
      { 
        points: [transformed.J, transformed.K, transformed.L], 
        color: 0x4444ff, 
        name: 'JKL',
        scale: scaleInfo,
        opacity: opacity,
        level: level
      },
      { 
        points: [transformed.M, transformed.N, transformed.O, transformed.P], 
        color: 0x8844ff, 
        name: 'MNOP',
        scale: scaleInfo,
        opacity: opacity,
        level: level
      }
    ];

    patterns.push(...shapes);
    return patterns;
  };

  // Apply curvature transformation
  const applyCurvature = (point, curvature) => {
    if (curvature === 0) return [...point, 0];

    const r = Math.sqrt(point[0] * point[0] + point[1] * point[1]);

    return [
      point[0],
      point[1], 
      curvature * r * r * 0.1 // Z displacement for curvature
    ];
  };

  // Create Three.js geometry from pattern
  const createGeometry = (patterns) => {
    if (!groupRef.current) return;

    // Clear existing geometry
    while (groupRef.current.children.length > 0) {
      const child = groupRef.current.children[0];
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
      groupRef.current.remove(child);
    }

    patterns.forEach((pattern, index) => {
      const { points, color, opacity = 0.7, isBaseConstruction = false } = pattern;

      // Apply curvature if enabled
      const curvedPoints = points.map(p => 
        applyCurvature(p, params.enableCurvedSurface ? params.curvature : 0)
      );

      // Create filled geometry
      if (params.renderMode === 'filled' || params.renderMode === 'both') {
        const shape = new THREE.Shape();
        if (curvedPoints.length > 0) {
          const firstPoint = curvedPoints[0];
          shape.moveTo(firstPoint[0], firstPoint[1]);

          for (let i = 1; i < curvedPoints.length; i++) {
            shape.lineTo(curvedPoints[i][0], curvedPoints[i][1]);
          }
          shape.lineTo(firstPoint[0], firstPoint[1]);
        }

        const geometry = new THREE.ShapeGeometry(shape);
        const material = new THREE.MeshBasicMaterial({ 
          color, 
          transparent: true, 
          opacity: opacity * (isBaseConstruction ? 1 : 0.7),
          side: THREE.DoubleSide
        });

        const mesh = new THREE.Mesh(geometry, material);
        if (params.enableCurvedSurface) {
          // Apply Z displacement for curvature
          const positions = geometry.attributes.position.array;
          for (let i = 0; i < positions.length; i += 3) {
            const x = positions[i];
            const y = positions[i + 1];
            const r = Math.sqrt(x * x + y * y);
            positions[i + 2] = params.curvature * r * r * 0.1;
          }
          geometry.attributes.position.needsUpdate = true;
        }

        groupRef.current.add(mesh);
      }

      // Create wireframe
      if (params.renderMode === 'wireframe' || params.renderMode === 'both') {
        const wireframeGeometry = new THREE.BufferGeometry();
        const vertices = [];

        for (let i = 0; i < curvedPoints.length; i++) {
          const current = curvedPoints[i];
          const next = curvedPoints[(i + 1) % curvedPoints.length];

          vertices.push(current[0], current[1], current[2] || 0);
          vertices.push(next[0], next[1], next[2] || 0);
        }

        wireframeGeometry.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));

        const wireframeMaterial = new THREE.LineBasicMaterial({ 
          color: isBaseConstruction ? 0x000000 : 0x333333, 
          linewidth: isBaseConstruction ? 3 : 1,
          transparent: true,
          opacity: opacity * (isBaseConstruction ? 1 : 0.8)
        });

        const wireframe = new THREE.LineSegments(wireframeGeometry, wireframeMaterial);
        groupRef.current.add(wireframe);
      }
    });
  };

  // Initialize Three.js scene with perfect square viewport
  useEffect(() => {
    if (!mountRef.current) return;

    // Scene setup
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0xf8f8f8);
    sceneRef.current = scene;

    // Perfect square camera setup
    const camera = new THREE.OrthographicCamera(
      -params.viewportSize / 2, // left
      params.viewportSize / 2,  // right
      params.viewportSize / 2,  // top
      -params.viewportSize / 2, // bottom
      0.1,
      1000
    );
    camera.position.set(0, 0, 10);
    cameraRef.current = camera;

    // Square renderer setup
    const size = 600; // Square size
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(size, size); // Perfect square
    rendererRef.current = renderer;
    mountRef.current.appendChild(renderer.domElement);

    // Controls group
    const group = new THREE.Group();
    scene.add(group);
    groupRef.current = group;

    // Grid helper for reference
    const gridHelper = new THREE.GridHelper(params.viewportSize, 20, 0x888888, 0xcccccc);
    gridHelper.rotation.x = Math.PI / 2;
    scene.add(gridHelper);

    return () => {
      if (mountRef.current && renderer.domElement) {
        mountRef.current.removeChild(renderer.domElement);
      }
      renderer.dispose();
    };
  }, [params.viewportSize]);

  // Update pattern when parameters change
  useEffect(() => {
    if (!groupRef.current) return;

    let patterns;
    if (params.tilingMode === 'hierarchical') {
      patterns = generateHierarchicalTiling();
    } else if (params.tilingMode === 'uniform') {
      patterns = generateUniformTiling();
    } else {
      patterns = generateBaseConstruction();
    }

    createGeometry(patterns);

    console.log(`Generated ${patterns.length} patterns in ${params.tilingMode} mode`);
  }, [params, theta, scaleHierarchy]);

  // Animation loop
  useEffect(() => {
    const animate = () => {
      if (params.rotationSpeed !== 0 && groupRef.current) {
        groupRef.current.rotation.z += params.rotationSpeed * 0.01;
      }

      if (rendererRef.current && sceneRef.current && cameraRef.current) {
        rendererRef.current.render(sceneRef.current, cameraRef.current);
      }

      animationRef.current = requestAnimationFrame(animate);
    };

    animate();

    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, [params.rotationSpeed]);

  return (
    <div className="w-full h-screen bg-gray-100 flex">
      {/* Control Panel */}
      <div className="w-80 bg-white shadow-lg p-4 overflow-y-auto">
        <h2 className="text-xl font-bold mb-4 text-gray-800">Optimal Tiling Framework</h2>

        {/* Tiling Mode */}
        <div className="mb-6">
          <h3 className="font-semibold mb-2 text-gray-700">Tiling Mode</h3>
          <div className="space-y-2">
            <div>
              <label className="block text-sm">Mode</label>
              <select
                value={params.tilingMode}
                onChange={(e) => setParams(p => ({ ...p, tilingMode: e.target.value }))}
                className="w-full p-2 border rounded"
              >
                <option value="base-only">Base Construction Only</option>
                <option value="hierarchical">Hierarchical Gap-Filling</option>
                <option value="uniform">Uniform All Scales</option>
              </select>
            </div>

            {params.tilingMode === 'base-only' && (
              <div>
                <label className="flex items-center">
                  <input
                    type="checkbox"
                    checked={params.showBaseConstruction}
                    onChange={(e) => setParams(p => ({ ...p, showBaseConstruction: e.target.checked }))}
                    className="mr-2"
                  />
                  Show as Connected Outline
                </label>
              </div>
            )}

            {params.tilingMode === 'hierarchical' && (
              <div>
                <label className="block text-sm">Hierarchical Depth: {params.hierarchicalDepth}</label>
                <input
                  type="range"
                  min="1"
                  max="6"
                  step="1"
                  value={params.hierarchicalDepth}
                  onChange={(e) => setParams(p => ({ ...p, hierarchicalDepth: parseInt(e.target.value) }))}
                  className="w-full"
                />
              </div>
            )}
          </div>
        </div>

        {/* Visual Controls */}
        <div className="mb-6">
          <h3 className="font-semibold mb-2 text-gray-700">Visual Style</h3>
          <div className="space-y-2">
            <div>
              <label className="block text-sm">Render Mode</label>
              <select
                value={params.renderMode}
                onChange={(e) => setParams(p => ({ ...p, renderMode: e.target.value }))}
                className="w-full p-2 border rounded"
              >
                <option value="both">Both (Filled + Wireframe)</option>
                <option value="filled">Filled Only</option>
                <option value="wireframe">Wireframe Only</option>
              </select>
            </div>
            <div>
              <label className="block text-sm">Viewport Size: {params.viewportSize}</label>
              <input
                type="range"
                min="5"
                max="50"
                step="5"
