    @jax.jit
    def calculate_coverage_gpu_core(centroids, scales, bounds_array, x_range, y_range):
        """Core GPU coverage calculation with pre-computed ranges"""
        # Create grid using pre-computed ranges
        grid_x, grid_y = jnp.meshgrid(x_range, y_range)
        test_points = jnp.stack([grid_x.ravel(), grid_y.ravel()], axis=-1)

        # Calculate distances using broadcasting (no loops!)
        distances = jnp.linalg.norm(
            test_points[:, None, :] - centroids[None, :, :], axis=-1
        )

        # Coverage calculation
        coverage_radii = scales * CONFIG.COVERAGE_RADIUS_MULTIPLIER
        coverage_strength = jnp.exp(-(distances / coverage_radii)**2)
        is_covered = jnp.any(coverage_strength > CONFIG.COVERAGE_THRESHOLD, axis=1)

        return jnp.mean(is_covered)

    def calculate_coverage_gpu(centroids, scales, bounds_array, resolution):
        """GPU-accelerated coverage calculation with resolution handling"""
        # Pre-compute ranges outside of JIT
        x_range = jnp.linspace(bounds_array[0], bounds_array[2], resolution)
        y_range = jnp.linspace(bounds_array[1], bounds_array[3], resolution)

        # Call JIT-compiled core function
        return calculate_coverage_gpu_core(centroids, scales, bounds_array, x_range, y_range)

    @jax.jit
    def evaluate_placement_batch_gpu_core(positions, existing_centroids, existing_scales, scale, bounds_array):
        """Core GPU placement evaluation"""
        # Distance to existing elements
        if existing_centroids.shape[0] > 0:
            distances_to_existing = jnp.linalg.norm(
                positions[:, None, :] - existing_centroids[None, :, :], axis=-1
            )
            min_distances = jnp.min(distances_to_existing / (scale + existing_scales), axis=1)
        else:
            min_distances = jnp.ones(positions.shape[0])

        # Distance from center
        center = jnp.array([(bounds_array[0] + bounds_array[2])/2, (bounds_array[1] + bounds_array[3])/2])
        distances_from_center = jnp.linalg.norm(positions - center, axis=1)
        max_distance = jnp.sqrt((bounds_array[2] - bounds_array[0])**2 + (bounds_array[3] - bounds_array[1])**2) / 2

        # Scoring
        separation_scores = jnp.minimum(1.0, min_distances / 2.0)
        center_scores = 1.0 - (distances_from_center / max_distance)

        total_scores = separation_scores * 0.7 + center_scores * 0.3
        return total_scores

