    """Calculate coverage with optional GPU acceleration and error handling"""
    if not self.placed_elements:
        return 0.0

    resolution = resolution or self.config.COVERAGE_RESOLUTION

    if self.config.USE_GPU_ACCELERATION and JAX_AVAILABLE:
        try:
            # GPU-accelerated version
            centroids = np.array([e.centroid for e in self.placed_elements])
