const TAU = 2 * Math.PI;
const TAU_NEG_QUARTER = Math.pow(TAU, -0.25);

// Log-grid discretization for (0,∞)
function makeLogGrid(uMin = -6, uMax = 6, M = 1001) {
    const u = [];
    const r = [];
    const du = (uMax - uMin) / (M - 1);

    for (let i = 0; i < M; i++) {
        const ui = uMin + i * du;
        u.push(ui);
        r.push(Math.exp(ui));
    }

    return { u, r, du };
}

// Linear interpolation on u-grid
function interpolateFunction(u, fVals, uQuery) {
    if (uQuery <= u[0]) return fVals[0];
    if (uQuery >= u[u.length - 1]) return fVals[fVals.length - 1];

    // Find surrounding points
    let i = 0;
    while (i < u.length - 1 && u[i + 1] < uQuery) i++;

    if (i >= u.length - 1) return fVals[fVals.length - 1];

    const t = (uQuery - u[i]) / (u[i + 1] - u[i]);
    return fVals[i] * (1 - t) + fVals[i + 1] * t;
}

// Apply L_τ operator
function applyLTau(fVals, grid) {
    const { u, r, du } = grid;
    const result = [];

    for (let j = 0; j < u.length; j++) {
        // Map u_j -> u' = -log(τ) - u_j
        const uPrime = -Math.log(TAU) - u[j];

        // Interpolate f at u'
        const fAtUPrime = interpolateFunction(u, fVals, uPrime);

        // Apply prefactor τ^(-1/4) * r_j^(-1/2)
        const prefactor = TAU_NEG_QUARTER * Math.pow(r[j], -0.5);
        result.push(prefactor * fAtUPrime);
    }

    return result;
}

// L2 norm on log-grid
function l2Norm(fVals, du) {
    let sum = 0;
    for (let i = 0; i < fVals.length; i++) {
        const val = fVals[i];
        if (typeof val === 'object') {
            // Complex number
            sum += val.real * val.real + val.imag * val.imag;
        } else {
            sum += val * val;
        }
    }
    return Math.sqrt(sum * du);
}

// Mellin character f(r) = r^(σ - 1/2 + it)
function mellonCharacter(u, sigma = 0.5, t = 0) {
    const result = [];
    for (let i = 0; i < u.length; i++) {
        const exponent = (sigma - 0.5) * u[i] + t * u[i];
        if (t === 0) {
            result.push(Math.exp(exponent));
        } else {
            // Complex result
            result.push({
                real: Math.exp((sigma - 0.5) * u[i]) * Math.cos(t * u[i]),
                imag: Math.exp((sigma - 0.5) * u[i]) * Math.sin(t * u[i])
            });
        }
    }
    return result;
}

// Test involution error ||L²f - f|| / ||f||
function testInvolutionError(fVals, grid) {
    const Lf = applyLTau(fVals, grid);
    const L2f = applyLTau(Lf, grid);

    // Compute ||L²f - f|| / ||f||
    const diff = [];
    for (let i = 0; i < fVals.length; i++) {
        if (typeof fVals[i] === 'object') {
            diff.push({
                real: L2f[i].real - fVals[i].real,
                imag: L2f[i].imag - fVals[i].imag
            });
        } else {
            diff.push(L2f[i] - fVals[i]);
        }
    }

    const normDiff = l2Norm(diff, grid.du);
    const normF = l2Norm(fVals, grid.du);

    return normDiff / (normF + 1e-12);
}

// Test norm preservation ||Lf|| vs ||f||
function testNormPreservation(fVals, grid) {
    const Lf = applyLTau(fVals, grid);

    const normF = l2Norm(fVals, grid.du);
    const normLf = l2Norm(Lf, grid.du);

    return Math.abs(normLf - normF) / (normF + 1e-12);
}

