function analyzeSinFunction(k, maxN = 50) {
    console.log(`\nAnalyzing k = ${k}:`);
    console.log("=".repeat(15));

    const tauToNegK = Math.pow(tau, -k);
    console.log(`τ^(-${k}) = ${tauToNegK.toExponential(6)}`);

    const results = [];

    for (let n = 0; n <= maxN; n++) {
        // Calculate ne^(iτ^(-k))
        // e^(iθ) = cos(θ) + i*sin(θ)
        const theta = tauToNegK;
        const realPart = n * Math.cos(theta);
        const imagPart = n * Math.sin(theta);

        // Calculate sin(ne^(iτ^(-k)))
        // sin(a + bi) = sin(a)*cosh(b) + i*cos(a)*sinh(b)
        const sinReal = Math.sin(realPart) * Math.cosh(imagPart);
        const sinImag = Math.cos(realPart) * Math.sinh(imagPart);

        // For sin^(-1), we need 1/sin(z)
        const sinMagnitudeSquared = sinReal * sinReal + sinImag * sinImag;
        const invSinReal = sinReal / sinMagnitudeSquared;
        const invSinImag = -sinImag / sinMagnitudeSquared;

        // Calculate sin(-ne^(iτ^(-k))) = -sin(ne^(iτ^(-k)))
        const negativeSinReal = -sinReal;
        const negativeSinImag = -sinImag;

        // Store the real parts (positions on real line)
        const pos1 = invSinReal;  // Real part of sin^(-1)
        const pos2 = negativeSinReal;  // Real part of -sin

        // Calculate distances from 0 and 1
        const dist1From0 = Math.abs(pos1);
        const dist1From1 = Math.abs(pos1 - 1);
        const dist2From0 = Math.abs(pos2);
        const dist2From1 = Math.abs(pos2 - 1);

        results.push({
            n,
            tauToNegK,
            realPart,
            imagPart,
            sinReal,
            sinImag,
            invSinReal: pos1,
            negativeSinReal: pos2,
            dist1From0,
            dist1From1,
            dist2From0,
            dist2From1
        });
    }

    return results;
}

