function createBeatingPattern(freq1, freq2, duration = 4*Math.PI, samples = 1000) {
    const pattern = [];
    const dt = duration / samples;

    for (let i = 0; i < samples; i++) {
        const t = i * dt;
        const wave1 = Math.sin(freq1 * t);
        const wave2 = Math.sin(freq2 * t);
        const combined = wave1 + wave2;
        pattern.push({
            t: t,
            wave1: wave1,
            wave2: wave2,
            combined: combined,
            envelope: 2 * Math.cos((freq1 - freq2) * t / 2)
        });
    }
    return pattern;
}

